*=====================================================================* * * * Kurzdokumentation : * * * * Bereich . . . : SLCJOB * RADDAT * Objekt . . . : SLCJOB * RADDAT * Beschreibung : Select Job * RADDAT * Author . . . : Thomas Raddatz <thomas.raddatz@tools400.de> * * Datum . . . . : 16.08.2007 * RADDAT * * *=====================================================================* * History: * * * * Datum Name Änderung * * ---------- ------------ --------------------------------------- * * 23.05.2013 Th.Raddatz Fixed problem, that SFLEND was not * * properly displayed. (End/More...) * * * *=====================================================================* * * * This software is free software, you can redistribute it and/or * * modify it under the terms of the GNU General Public License (GPL) * * as published by the Free Software Foundation. * * * * See GNU General Public License for details. * * http://www.opensource.org * * http://www.opensource.org/licenses/gpl-license.html * * * *=====================================================================* * >>PRE-COMPILER<< * * * * >>CRTCMD<< CRTRPGMOD MODULE(&LI/&OB) + * * SRCFILE(&SL/&SF) + * * SRCMBR(&SM); * * * * >>COMPILE<< * * >>PARM<< TRUNCNBR(*NO); * * >>PARM<< DBGVIEW(*LIST); * * >>PARM<< TGTRLS(V5R2M0); * RADDAT * >>END-COMPILE<< * * * * >>EXECUTE<< * * * * >>END-PRE-COMPILER<< * *=====================================================================* H DEBUG RADDAT H OPTION(*SRCSTMT : *NODEBUGIO) RADDAT H DECEDIT('0,') DATEDIT(*DMY.) RADDAT H DATFMT(*ISO ) TIMFMT(*ISO ) RADDAT H EXPROPTS(*RESDECPOS) RADDAT H EXTBININT(*YES) RADDAT H COPYRIGHT('V1.1 - 23.05.2013 - mailto: thomas.raddatz@tools400.de') RADDAT *=====================================================================* FSLCJOBFM CF E WORKSTN usropn RADDAT F extfile(g_dspF) F indds(workstnInd) F infds(workstnInf) F SFILE(PBSFL: g_sflrrn) * D g_dspF S 21A inz D g_sflrrn S 5I 0 inz * D workstnInd DS qualified D sflNxtChg 84 84N D ##OPTION_RI 85 85N D ##OPTION_PC 86 86N D sflDsp 80 80N D sflDspCtl 81 81N D sflClr 82 82N D sflEnd 83 83N D isWideScreen 88 88N * RADDAT D workstnInf DS likeds(workstn_infds_t) RADDAT * * ------------------------------------ * Type definitions * ------------------------------------ CPY /COPY QSLCJOB,WORKSTN RADDAT CPY /COPY QLSTJOB,FDJOBI0200 RADDAT CPY /COPY QLSTJOB,FDJOBI0400 RADDAT * * ------------------------------------ * External Prototypes * ------------------------------------ CPY /COPY QLSTJOB,PLSTJOB CPY /COPY QBASICS1,PBASICS1 * D QCMDEXC... D PR extpgm('QCMDEXC') D i_cmd 32702A const options(*varsize) D i_length 15P 5 const D i_IGC_control 3A const options(*nopass) * * Resend Escape Message (QMHRSNEM) API D QMHRSNEM... D PR extpgm('QMHRSNEM') D i_msgKey 4A const D io_ErrCode 32767A options(*varsize ) D i_callStkE 32767A const options(*nopass: *varsize) D i_lenStkE 10I 0 const options(*nopass) D i_fmtStkE 8A const options(*nopass) D i_frmStkEAdr 16A const options(*nopass) D i_frmStkECnt 10I 0 const options(*nopass) * * ------------------------------------ * Prototypes * ------------------------------------ /DEFINE SLCJOB_INTERNALLY RADDAT CPY /COPY QSLCJOB,PSLCJOB RADDAT /UNDEFINE SLCJOB_INTERNALLY RADDAT * D p_main... D PR D i_qJob const likeds(qJob_t ) D o_qJob likeds(qJob_t ) D o_cmdKey like(keyPressed_t) RADDAT D i_pJobValid * const procptr RADDAT * * Laden Subfile D lf_loadSubfile... D PR N D hJobs const like(lstJob_handle_t) * * Löschen Subfile D lp_clearSubfile... D PR * * Anzeigen Subfile, warten auf Benutzereingaben D lf_showScreen... D PR like(keyPressed_t) RADDAT * * Verarbeiten Subfile-Eingaben D lf_doSubfileOptions... D PR N D o_qJob likeds(qJob_t ) * * Lesen geänderten Subfile-Datensatz D lf_readc... D PR N D o_SUBFILE likerec(PBSFL) * * Prüfen Subfile-Datensatz D lf_isSubfileRecordValid... D PR N D i_SUBFILE_IN value likerec(PBSFL: *INPUT) * * Prüfen Subfile-Auswahl D lf_isSubfileOptionValid... D PR N D i_option value like(##OPTION) * * Löschen Subfile Fehlerbezugszahlen D lf_clearSubfileErrorIndicator... D PR * * Laden Texte für Subfiledatensatz D lf_loadSubfileText... D PR likerec(PBSFL: *OUTPUT) D i_SUBFILE_OUT likerec(PBSFL: *OUTPUT) * * Laden Update Image für Subfiledatensatz D lf_loadSubfileOutImage... D PR likerec(PBSFL: *OUTPUT) D i_SUBFILE_IN likerec(PBSFL: *INPUT ) * * Prüfen auf eindeutige Jobauswahl und ermitteln Job. D lf_getUniqueJob... D PR N D hJobs const like(lstJob_handle_t) D q1Job likeds(qJob_t ) * RADDAT * Prüfen, ob der Jobstatus gültig ist. RADDAT D lf_isJobValid... RADDAT D PR N RADDAT D jobl0100 const likeds(jobl0100_t ) RADDAT * * Initialisieren Programm D lp_initProgram... RADDAT D PR * * ------------------------------------ * Global fields * ------------------------------------ D g_pssr DS qualified D isActive N inz(cFalse) * * ------------------------------------ * Program Status Information * ------------------------------------ D sds SDS qualified D pgmName 1 10A D statusCode 11 15S 0 D statusCodePrv 16 20S 0 D srcLineNbr 21 28A D routine 29 36A D numParms 37 39S 0 D msgID 40 46A D excType 3A overlay(msgID) D excNbr 4A overlay(msgID: *next) D reserved_1 47 50A D msgWorkArea 51 80A D pgmLib 81 90A D msgText 91 170A D excpID 171 174A D lastFileUsed 175 184A D reserved_2 185 190A D jobDate 191 198A D century 199 200S 0 D lastFileUsed8 201 208A D lastFileStat 209 243A D job 244 253A D user 254 263A D nbr 264 269A D pgmDate 270 275S 0 D date 276 281S 0 D time 282 287S 0 D pgmCrtDate 288 293A D pgmCrtTime 294 299A D compilerLvl 300 303A D srcFile 304 313A D srcLib 314 323A D srcMbr 324 333A D prcOfPgm 334 343A D prcOfMod 344 353A D Reserved 354 429A D curUsrPrf 358 367A * *===============================================================* * Program Entry Point *===============================================================* D SLCJOB... RADDAT D PI D gi_qJob const likeds(qJob_t ) D go_qJob likeds(qJob_t ) D go_cmdKey like(keyPressed_t) RADDAT D gi_pJobValid * const procptr options(*nopass) RADDAT * RADDAT D p_pJobValid C const(4) RADDAT * D pJobValid S * procptr inz RADDAT D errCode DS likeds(errCode_t ) inz * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE //RADDAT B01 if %parms() >= p_pJobValid; //RADDAT pJobValid = gi_pJobValid; //RADDAT X01 else; //RADDAT pJobValid = *NULL; //RADDAT E01 endif; //RADDAT
p_main(gi_qJob: go_qJob: go_cmdKey: pJobValid); //RADDAT
*inlr = *on;
return;
// - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - // Error handle // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
begsr *PSSR;
B01 if not g_pssr.isActive; g_pssr.isActive = cTrue;
errCode = f_newApiErRCode(cTrue); QMHRSNEM('': errCode);
E01 endif;
endsr '*CANCL';
/END-FREE * *===============================================================* * Haupsteuerung *===============================================================* P p_main... P B * D p_main... D PI D i_qJob const likeds(qJob_t ) D o_qJob likeds(qJob_t ) D o_cmdKey like(keyPressed_t) RADDAT D i_pJobValid * const procptr RADDAT * * Schleifensteuerung D isDone S N inz(cFalse) D isError S N inz(cFalse) D doShowScreen S N inz(cTrue ) D key S like(keyPressed_t ) inz RADDAT * * Hilfsfelder D hJobs S like(lstJob_handle_t) inz D q1Job DS likeds(qJob_t ) inz D jobl0100 DS likeds(jobl0100_t ) inz RADDAT D jobi0200 DS likeds(jobi0200_t ) inz RADDAT D msg DS likeds(msg_t ) inz * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
// Initialisieren Programm lp_initProgram(); //RADDAT //RADDAT // Set procedure to check whether is to be listed or not. //RADDAT B01 if i_pJobValid <> *NULL; //RADDAT g_SLCJOB_cb_isJobValid = i_pJobValid; //RADDAT X01 else; //RADDAT g_SLCJOB_cb_isJobValid = %paddr('LF_ISJOBVALID'); //RADDAT E01 endif; //RADDAT
// Tue es , bis wir fertig sind oder ein Fehler auftritt: B01 dou isDone or isError;
// Abrufen Job-Liste f_opnJobLst(i_qJob.name: i_qJob.user: i_qJob.nbr: cLSTJOB_STATUS_ALL: cLSTJOB_ORDERBY_NAME_DESC: hJobs);
// Wenn nur 1 Job den Suchkriterien entspricht, ... B02 if lf_getUniqueJob(hJobs: q1Job); // ... dann diesen Job direkt als gefunden // zurück geben. o_qJob = q1Job; // ... fake that ENTER was pressed key = cKeyEnter; //RADDAT // ... leave processing loop isDone = cTrue; leave; E02 endif;
// Öffnen Bildschirmdatei g_dspF = %trim(sds.pgmLib) + '/' + 'SLCJOBFM'; //RADDAT open SLCJOBFM; //RADDAT
// Füllen Subfile lf_loadSubfile(hJobs);
// Ausgeben Bildschirm doShowScreen = cTrue;
B02 dow doShowScreen;
key = lf_showScreen();
// Verarbeiten Eingabe für ... B03 select; // ... F3 when key = cKeyF3; //RADDAT doShowScreen = cFalse; // ... F5 when key = cKeyF5; //RADDAT B04 if (not HANDLE_isNull(hJobs)); f_cloJobLst(hJobs); E04 endif; f_opnJobLst(i_qJob.name: i_qJob.user: i_qJob.nbr: cLSTJOB_STATUS_ALL: cLSTJOB_ORDERBY_NAME_DESC: hJobs); lf_loadSubfile(hJobs); doShowScreen = cTrue; // ... F12 when key = cKeyF12; //RADDAT doShowScreen = cFalse; // ... ENTER when key = cKeyEnter; //RADDAT B04 if lf_doSubfileOptions(o_qJob); doShowScreen = cTrue; X04 else; doShowScreen = cFalse; E04 endif; E03 endsl;
E02 enddo;
// Everything is done isDone = cTrue; E01 enddo;
o_cmdKey = key;
// Schließen Bildschirmdatei B01 if %open(SLCJOBFM); //RADDAT close SLCJOBFM; //RADDAT g_dspF = ''; E01 endif;
// Schließen Liste der Jobs B01 if (not HANDLE_isNull(hJobs)); f_cloJobLst(hJobs); E01 endif;
return;
/END-FREE * P p_main... P E * *===============================================================* * Laden Subfile *===============================================================* P lf_loadSubfile... P B * D lf_loadSubfile... D PI N D hJobs const like(lstJob_handle_t) * * Return value D isData S N inz(cFalse) * * Schleifensteuerung D isDone S N inz(cFalse) D isError S N inz(cFalse) * * Hilfsfelder D x S 10I 0 inz D ds_SUBFILE_OUT DS likerec(PBSFL: *OUTPUT) inz D msg DS likeds(msg_t ) inz D jobl0100 DS likeds(jobl0100_t ) inz RADDAT D jobi0200 DS likeds(jobi0200_t ) inz RADDAT D jobi0400 DS likeds(jobi0400_t ) inz RADDAT * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
// Löschen Subfile lp_clearSubfile();
// Lesen Jobs B01 for x = 1 to f_getNumJobAvl(hJobs);
// Abrufen ersten/nächsten Job B02 if x = 1; f_getFirstJob(hJobs: jobl0100); X02 else; f_getNextJob(hJobs: jobl0100); E02 endif;
B02 if SLCJOB_cb_isJobValid(jobl0100); //RADDAT
// Abrufen zusätzlicher Job-Attribute jobi0200 = f_rtvJobA(jobl0100.intJobID: 'JOBI0200': msg); jobi0400 = f_rtvJobA(jobl0100.intJobID: 'JOBI0400': msg);
// Löschen Subfile-Felder clear ds_SUBFILE_OUT;
// Laden versteckte Felder ds_SUBFILE_OUT.H_JOB = jobi0400.job; ds_SUBFILE_OUT.H_USER = jobi0400.user; ds_SUBFILE_OUT.H_NBR = jobi0400.nbr; ds_SUBFILE_OUT.H_TYPE = jobi0400.type; ds_SUBFILE_OUT.H_STATUS = jobi0400.status; ds_SUBFILE_OUT.H_ACTJOBST = jobi0200.actJobSts; ds_SUBFILE_OUT.H_DATTIMEN = jobi0400.dateTimeEnt; //RADDAT
// Laden sichtbare Felder ds_SUBFILE_OUT.##OPTION = 0;
// Laden Texte und Bezeichnungen ds_SUBFILE_OUT = lf_loadSubfileText(ds_SUBFILE_OUT);
lf_clearSubfileErrorIndicator(); workstnInd.sflNxtChg = cFalse;
g_sflrrn = g_sflrrn + 1; write PBSFL ds_SUBFILE_OUT;
// Anzeigen Subfile Daten workstnInd.sflDsp = cTrue; isData = cTrue;
E02 endif; E01 endfor;
workstnInd.sflEnd = cTrue;
SFSANR = 1;
return isData;
/END-FREE * P lf_loadSubfile... P E * *===============================================================* * Löschen Subfile *===============================================================* P lp_clearSubfile... P B * D lp_clearSubfile... D PI * * Schleifensteuerung D isDone S N inz(cFalse) D isError S N inz(cFalse) * * Hilfsfelder * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
workstnInd.sflDsp = cFalse; workstnInd.sflDspCtl = cFalse; workstnInd.sflClr = cTrue; workstnInd.sflEnd = cFalse;
write PBCTL;
workstnInd.sflDsp = cFalse; workstnInd.sflDspCtl = cTrue; workstnInd.sflClr = cFalse; workstnInd.sflEnd = cFalse;
g_sflrrn = 0;
return;
/END-FREE * P lp_clearSubfile... P E * *===============================================================* * Anzeigen Subfile, warten auf Benutzereingaben *===============================================================* P lf_showScreen... P B * D lf_showScreen... D PI like(keyPressed_t) RADDAT * * Return value D key S like(keyPressed_t) inz RADDAT * * Hilfsfelder * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
write MSGCTL;
B01 if not workstnInd.sflDsp; write PBLEER; E01 endif;
write PBBOT;
exfmt PBCTL;
key = workstnInf.AID; //RADDAT
return key;
/END-FREE * P lf_showScreen... P E * *===============================================================* * Verarbeiten Subfile-Eingaben *===============================================================* P lf_doSubfileOptions... P B * D lf_doSubfileOptions... D PI N D o_qJob likeds(qJob_t ) * * Return value D isChanged S N inz(cTrue) * * Hilfsfelder D isError S N inz(cFalse) D cmd S 2048A varying inz D option S like(ds_SUBFILE_OUT.##OPTION) inz D sflRrn DS qualified inz D firstError 5I 0 D lastChanged 5I 0 D ds_SUBFILE_IN DS likerec(PBSFL: *INPUT ) D ds_SUBFILE_OUT DS likerec(PBSFL: *OUTPUT) * * Konstanten D cEOF C const(*ON ) RADDAT D cCMD_WRKJOB... D C const('WRKJOB + D JOB(&NBR/&USER/&JOB)') D cCMD_WRKJOB_SPLF... D C const('WRKJOB + D JOB(&NBR/&USER/&JOB) + D OPTION(*SPLF)') * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
clear sflRrn;
clear o_qJob;
B01 dow (lf_readc(ds_SUBFILE_IN) <> cEOF) and (o_qJob = '');
lf_clearSubfileErrorIndicator();
B02 if ds_SUBFILE_IN.##OPTION = 0; isError = cFalse; workstnInd.sflNxtChg = cFalse; X02 else; B03 if not lf_isSubfileRecordValid(ds_SUBFILE_IN); isError = cTrue; workstnInd.sflNxtChg = cTrue; X03 else; isError = cFalse; workstnInd.sflNxtChg = cFalse; E03 endif; E02 endif;
// Füllen Subfiledatensatz für Update ds_SUBFILE_OUT = lf_loadSubfileOutImage(ds_SUBFILE_IN);
B02 if not isError; option = ds_SUBFILE_OUT.##OPTION; ds_SUBFILE_OUT.##OPTION = 0; E02 endif;
// Aktualisieren Subfiledatensatz update PBSFL ds_SUBFILE_OUT;
// Beibehalten Cursor-Position sflrrn.lastChanged = g_sflRrn;
// Verlassen Schleife bei Fehler = Satz zur Änderung markiert B02 if isError; B03 if sflRrn.firstError = 0; sflrrn.firstError = g_sflRrn; E03 endif; leave; E02 endif;
// Verarbeiten Subfileauswahl B02 select; when option = 1; o_qJob.name = ds_SUBFILE_OUT.H_JOB; o_qJob.user = ds_SUBFILE_OUT.H_USER; o_qJob.nbr = ds_SUBFILE_OUT.H_NBR; isChanged = cFalse; when option = 5; cmd = cCMD_WRKJOB; cmd = f_replace('&NBR' : %trim(ds_SUBFILE_OUT.H_NBR ): cmd); cmd = f_replace('&USER': %trim(ds_SUBFILE_OUT.H_USER): cmd); cmd = f_replace('&JOB' : %trim(ds_SUBFILE_OUT.H_JOB ): cmd); QCMDEXC(cmd: %len(cmd)); isChanged = cTrue; when option = 8; cmd = cCMD_WRKJOB_SPLF; cmd = f_replace('&NBR' : %trim(ds_SUBFILE_OUT.H_NBR ): cmd); cmd = f_replace('&USER': %trim(ds_SUBFILE_OUT.H_USER): cmd); cmd = f_replace('&JOB' : %trim(ds_SUBFILE_OUT.H_JOB ): cmd); QCMDEXC(cmd: %len(cmd)); isChanged = cTrue; E02 endsl; E01 enddo;
// Positionieren Cursor B01 if sflrrn.firstError > 0; SFSANR = sflRrn.firstError; E01 endif;
return isChanged;
/END-FREE * P lf_doSubfileOptions... P E * *===============================================================* * Lesen geänderten Subfile-Datensatz *===============================================================* P lf_readc... P B * D lf_readc... D PI N D o_SUBFILE likerec(PBSFL) * * Return value D isEOF S N inz(cFalse) * * Hilfsfelder * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
readc PBSFL o_SUBFILE; B01 if %eof(SLCJOBFM); //RADDAT isEOF = cTrue; X01 else; isEOF = cFalse; E01 endif;
return isEOF;
/END-FREE * P lf_readc... P E * *===============================================================* * Prüfen Subfile-Datensatz *===============================================================* P lf_isSubfileRecordValid... P B * D lf_isSubfileRecordValid... D PI N D i_SUBFILE_IN value likerec(PBSFL: *INPUT) * * Return value D isValid S N inz(cFalse) * * Hilfsfelder D isError S N inz(cFalse) * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
B01 dou isError or isValid; B02 if not lf_isSubfileOptionValid(i_SUBFILE_IN.##OPTION); workstnInd.##OPTION_RI = cTrue; workstnInd.##OPTION_PC = cTrue; isError = cTrue; leave; E02 endif;
isValid = cTrue; E01 enddo;
return isValid;
/END-FREE * P lf_isSubfileRecordValid... P E * *===============================================================* * Prüfen Subfile-Auswahl *===============================================================* P lf_isSubfileOptionValid... P B * D lf_isSubfileOptionValid... D PI N D i_option value like(##OPTION) * * Return value D isValid S N inz(cFalse) * * Hilfsfelder * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
B01 if (i_option = 1) or (i_option = 5) or (i_option = 8); isValid = cTrue; isValid = cTrue; X01 else; isValid = cFalse; E01 endif;
return isValid;
/END-FREE * P lf_isSubfileOptionValid... P E * *===============================================================* * Löschen Subfile Fehlerbezugszahlen *===============================================================* P lf_clearSubfileErrorIndicator... P B * D lf_clearSubfileErrorIndicator... D PI * * Hilfsfelder * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
workstnInd.##OPTION_RI = cFalse; workstnInd.##OPTION_PC = cFalse;
return;
/END-FREE * P lf_clearSubfileErrorIndicator... P E * *===============================================================* * Laden Texte für Subfiledatensatz *===============================================================* P lf_loadSubfileText... P B * D lf_loadSubfileText... D PI likerec(PBSFL: *OUTPUT) D i_SUBFILE_OUT likerec(PBSFL: *OUTPUT) * * Return value D ds_SUBFILE_OUT DS likerec(PBSFL: *OUTPUT) inz * * Hilfsfelder * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
ds_SUBFILE_OUT = i_SUBFILE_OUT;
ds_SUBFILE_OUT.$$JOB = ds_SUBFILE_OUT.H_JOB; ds_SUBFILE_OUT.$$USER = ds_SUBFILE_OUT.H_USER; ds_SUBFILE_OUT.$$NBR = ds_SUBFILE_OUT.H_NBR;
B01 select; when ds_SUBFILE_OUT.H_TYPE = 'A'; ds_SUBFILE_OUT.$$TYPE = 'AUTO'; when ds_SUBFILE_OUT.H_TYPE = 'B'; ds_SUBFILE_OUT.$$TYPE = 'BATCH'; when ds_SUBFILE_OUT.H_TYPE = 'I'; ds_SUBFILE_OUT.$$TYPE = 'INTER'; when ds_SUBFILE_OUT.H_TYPE = 'M'; ds_SUBFILE_OUT.$$TYPE = 'SBS'; when ds_SUBFILE_OUT.H_TYPE = 'R'; ds_SUBFILE_OUT.$$TYPE = 'RDR'; when ds_SUBFILE_OUT.H_TYPE = 'S'; ds_SUBFILE_OUT.$$TYPE = 'SYS'; when ds_SUBFILE_OUT.H_TYPE = 'W'; ds_SUBFILE_OUT.$$TYPE = 'WTR'; when ds_SUBFILE_OUT.H_TYPE = 'X'; ds_SUBFILE_OUT.$$TYPE = 'SCPF'; E01 endsl;
B01 select; when ds_SUBFILE_OUT.H_STATUS = '*ACTIVE'; ds_SUBFILE_OUT.$$STATUS = 'ACTIVE'; when ds_SUBFILE_OUT.H_STATUS = '*JOBQ'; ds_SUBFILE_OUT.$$STATUS = 'JOBQ'; when ds_SUBFILE_OUT.H_STATUS = '*OUTQ'; ds_SUBFILE_OUT.$$STATUS = 'OUTQ'; E01 endsl;
%subst(ds_SUBFILE_OUT.$$STATUS : 1 + %len(ds_SUBFILE_OUT.$$STATUS ) - %len(ds_SUBFILE_OUT.H_ACTJOBST) : %len(ds_SUBFILE_OUT.H_ACTJOBST) ) = ds_SUBFILE_OUT.H_ACTJOBST;
ds_SUBFILE_OUT.$$DATE = %char( %date(%subst(ds_SUBFILE_OUT.H_DATTIMEN: 1: 7): *CYMD0): *DMY); ds_SUBFILE_OUT.$$DATE = %xlate('/': '.': ds_SUBFILE_OUT.$$DATE);
return ds_SUBFILE_OUT;
/END-FREE * P lf_loadSubfileText... P E * *===============================================================* * Laden Update Image für Subfiledatensatz *===============================================================* P lf_loadSubfileOutImage... P B * D lf_loadSubfileOutImage... D PI likerec(PBSFL: *OUTPUT) D i_SUBFILE_IN likerec(PBSFL: *INPUT ) * * Return value D ds_SUBFILE_OUT DS likerec(PBSFL: *OUTPUT) inz * * Hilfsfelder * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
// Laden versteckte Felder ds_SUBFILE_OUT.H_JOB = i_SUBFILE_IN.H_JOB; ds_SUBFILE_OUT.H_USER = i_SUBFILE_IN.H_USER; ds_SUBFILE_OUT.H_NBR = i_SUBFILE_IN.H_NBR; ds_SUBFILE_OUT.H_TYPE = i_SUBFILE_IN.H_TYPE; ds_SUBFILE_OUT.H_STATUS = i_SUBFILE_IN.H_STATUS; ds_SUBFILE_OUT.H_ACTJOBST = i_SUBFILE_IN.H_ACTJOBST; ds_SUBFILE_OUT.H_DATTIMEN = i_SUBFILE_IN.H_DATTIMEN;
// Laden sichtbare Felder ds_SUBFILE_OUT.##OPTION = i_SUBFILE_IN.##OPTION;
// Laden Text und Bezeichnungen ds_SUBFILE_OUT = lf_loadSubfileText(ds_SUBFILE_OUT);
return ds_SUBFILE_OUT;
/END-FREE * P lf_loadSubfileOutImage... P E * *===============================================================* * Prüfen auf eindeutige Jobauswahl und ermitteln Job. *===============================================================* P lf_getUniqueJob... P B * D lf_getUniqueJob... D PI N D hJobs const like(lstJob_handle_t) D q1Job likeds(qJob_t ) * * Funktionswert D isUniqueJob S N inz(cFalse) * * Hilfsfelder D x S 10I 0 inz D numJobs S 10I 0 inz D ds_SUBFILE_OUT DS likerec(PBSFL: *OUTPUT) inz D msg DS likeds(msg_t ) inz D jobl0100 DS likeds(jobl0100_t ) inz RADDAT D tmpJobl0100 DS likeds(jobl0100 ) inz * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
// Lesen Jobs x = 1; numJobs = 0;
B01 dow (x <= f_getNumJobAvl(hJobs)) and (numJobs <= 1);
// Abrufen ersten/nächsten Job B02 if x = 1; f_getFirstJob(hJobs: jobl0100); X02 else; f_getNextJob(hJobs: jobl0100); E02 endif;
B02 if SLCJOB_cb_isJobValid(jobl0100); //RADDAT tmpJobl0100 = jobl0100; numJobs = numJobs + 1; E02 endif;
x = x + 1; E01 enddo;
B01 if numJobs = 1; q1Job.name = tmpJobl0100.job; q1Job.user = tmpJobl0100.user; q1Job.nbr = tmpJobl0100.nbr; isUniqueJob = cTrue; E01 endif;
return isUniqueJob;
/END-FREE * P lf_getUniqueJob... P E * *===============================================================* * Prüfen, ob der Jobstatus gültig ist. *===============================================================* P lf_isJobValid... RADDAT P B * D lf_isJobValid... RADDAT D PI N D jobl0100 const likeds(jobl0100_t ) RADDAT * * Funktionswert D isValid S N inz(cFalse) * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
isValid = cTrue; //RADDAT
return isValid;
/END-FREE * P lf_isJobValid... RADDAT P E * *===============================================================* * Initialisieren Programm *===============================================================* P lp_initProgram... RADDAT P B * D lp_initProgram... RADDAT D PI * * Hilfsfelder * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
§PGMQ = '*'; // Anzuzeigenden Nachrichtenwartesch
B01 if f_getDisplayMode() = cDISPLAY_MODE_DS3; workstnInd.isWideScreen = cFalse; // Bildschirmgröße 24x80 X01 else; workstnInd.isWideScreen = cTrue; // Bildschirmgröße 27x132 E01 endif;
return;
/END-FREE * P lp_initProgram... RADDAT P E *
